function renderReviewPathway(id){
 if(typeof reviewPaths==='undefined')return '';
 const path=reviewPaths.find(p=>p.stages.some(s=>s.id===id)||(p.unit===1&&id==='network-review'));if(!path)return '';
 const active=path.stages.find(s=>s.id===id);
 return `<aside class="review-pathway" aria-label="Review and exam preparation"><p class="eyebrow">REVIEW AND EXAM PREPARATION / UNIT ${path.unit}</p><h2>Choose the right revision stage</h2><p>${active?`<strong>This chapter: ${active.label}.</strong> ${active.purpose}`:'<strong>This chapter: diagnose networking.</strong> Apply network ideas together and identify gaps. This is a topic review, not a whole-unit diagnostic.'}</p><ol>${path.stages.map(s=>`<li${s.id===id?' aria-current="step"':''}><a href="#${s.id}"><strong>${s.label}</strong></a><p>${s.purpose}</p></li>`).join('')}</ol><p>${path.note}</p><p>Keep your first attempt, identify the cause of an error and retry after a gap. These are separate learning stages, not extra examinations or proof of mastery. For the shared written-question bank, choose <a href="practice/?mode=study">Study explained examples</a> or <a href="practice/?mode=timed">Timed practice</a>. Follow your teacher's allocated lessons and timing.</p></aside>`;
}
function renderPygamePreparation(id) {
  const lessons = {loops:'y11-1',functions:'y11-2',arrays:'y11-3',files:'y11-4','unit3-fluency':'y12-1','unit3-structures':'y12-2','unit3-objects':'y12-3','unit3-inheritance':'y12-4',design:'y11-1','unit3-project':'y12-1'};
  if (!lessons[id]) return '';
  return `<aside class="notice"><strong>Pygame preparation before the project.</strong> <a href="pygame/index.html#${lessons[id]}">Open the scaffolded practice lesson</a> with worked code, a changed faded task and expected/actual checks. <a href="pygame/readiness.csv" download>Record independent readiness</a> before assessment; the project workshops do not absorb first-use GUI teaching.</aside>`;
}
const textbookSectionLabels = {
  "Mark a criterion and explain its cause": "Check an explanation and its cause",
  "Submit, reflect and prepare for review": "Reflect and prepare for review",
  "Use the original 64-mark paper": "Use the original practice paper",
  "Mark, correct and explain limits": "Check, correct and explain limits",
  "Practice, then complete the controlled task": "Practice, then try it independently",
  "Submit evidence and evaluate against the requirements": "Check your evidence against the requirements",
  "Complete a controlled practice and feedback cycle": "Practice, check and try again"
};
const escapeHtml = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const readingOrder = ['start','values','representation','selection','loops','functions','arrays','files','design','software-responsibility','networks','addressing','network-design','network-review','consolidation','exam-preparation'];
function syllabusBasisNotice(ch) {
  return (ch.unit || 1) >= 3 ? '<aside class="notice syllabus-basis"><strong>2026 syllabus foundation · 2027 revisions.</strong> Valid 2026 technical references are retained. The revised syllabus applies to 2027 teaching. <a href="syllabus-basis.md">See the comparison and source editions</a>.</aside>' : '';
}
function coreWorkedExample(ch) {
  return `<h2>Worked Python example</h2><p>Predict the result first, then run and modify the downloaded file in your Python environment.</p><pre><code>${escapeHtml(ch.code)}</code></pre>`;
}
function lessonPage(ch){const order=ch.unit===4?['unit4-design','unit4-sql','unit4-project','unit4-analysis','unit4-controls','unit4-crypto','unit4-ethics','unit4-review','unit4-consolidation','unit4-exam']:ch.unit===3?['unit3-fluency','unit3-structures','unit3-search','unit3-sort','unit3-objects','unit3-inheritance','unit3-project','unit3-reliability','unit3-network-models','unit3-addressing','unit3-secure-networks','unit3-review','unit3-consolidation','unit3-exam']:ch.unit===2?['database-foundations','entities-relationships','normalisation','sql-basics','database-solution','security-threats','responsible-data','unit2-review','unit2-consolidation','unit2-exam']:readingOrder;const position=order.indexOf(ch.id);return `<article class="lesson"><p class="eyebrow">UNIT ${ch.unit||1} / WEEK ${ch.week} / CHAPTER ${position+1}</p><h1>${ch.title}</h1><p class="lede">${ch.intro}</p>${renderReviewPathway(ch.id)}${renderLessonPreparation(ch.id)}<span class="pill">${ch.badge||'PYTHON 3'}</span> <span class="pill">CLASSROOM DRAFT · REVIEW PENDING</span><div class="no-print" style="margin-top:20px"><button id="chapter-print">Print / save as PDF</button> ${ch.code?'<button id="chapter-download">Download example</button>':''}</div><h2>What you’ll learn</h2><div class="objectives"><ul>${ch.objectives.map(x=>`<li>${x}</li>`).join('')}</ul></div>${syllabusBasisNotice(ch)}${ch.sections.map(([title,html],i)=>`${ch.id === 'start' && i === 3 ? coreWorkedExample(ch) : ''}<section><h2${textbookSectionLabels[title] || /^Q\d+ · \d+ marks$/.test(title) ? ` id="${textbookHeadingId(title)}"` : ''}>${i+1}. ${textbookSectionLabels[title] || title.replace(/ · \d+ marks$/, '')}</h2>${html}</section>`).join('')}${ch.code && ch.id !== 'start' ? coreWorkedExample(ch) : ''}<section class="chapter-application"><h2>Your practical task</h2><div class="card"><p>${ch.task}</p><details><summary>Show illustrative answer / example</summary>${ch.code?`<pre><code>${escapeHtml(ch.solution)}</code></pre><p>Compare the logic and tests, not just the spelling of variable names.</p>`:`<p>${escapeHtml(ch.solution)}</p>`}</details></div></section><section class="chapter-reinforcement"><h2>Practice and explain</h2><p>Use these short checks to reinforce the chapter or follow your teacher’s allocation. Keep your first attempt, then compare the explained answer.</p>${ch.practice.map(([type,q,a])=>`<section class="practice"><p class="eyebrow">${type.replace(/ · \d+ marks$/, '')}</p><p>${q}</p><details><summary>Show explained answer</summary><p>${escapeHtml(a)}</p></details></section>`).join('')}<h3 id="heading-check-your-understanding">Check your understanding</h3><p>${ch.quiz.q}</p><div id="chapter-quiz">${ch.quiz.options.map((t,i)=>`<button class="quiz-option" data-choice="${i}">${escapeHtml(t)}</button>`).join(' ')}</div><p id="chapter-feedback" class="feedback" aria-live="polite"></p><p><a href="resources/#${ch.id}">More activities and resources for this chapter</a> · <a href="revision/#topic-${ch.id}">Revisit this topic after a gap</a></p></section><h2>Chapter recap</h2><p>${ch.recap}</p><details class="chapter-teacher-guidance"><summary>Teaching notes and classroom sequence</summary>${renderPygamePreparation(ch.id)}<p><a href="teachers/#topic-${ch.id}">Open the teacher planning notes</a> · <a href="curriculum/scope.html">Required skills, support-booklet material and enrichment</a> · <a href="curriculum/provision-review.html">Reviewed teaching and practice</a></p><ol>${ch.lessons.map(x=>`<li>${x}</li>`).join('')}</ol><p>${(ch.unit||1)===1&&ch.week===2?"Week 2 is shared by the values and representation chapters; their activities fit into four total lessons. ":""}This draft chapter provides learning activities and explained answers. It does not establish complete syllabus coverage.</p></details><p class="reference">Technical reference: <a href="${ch.reference}" target="_blank" rel="noopener">${ch.refTitle}</a>. Curriculum requirements: <a href="${source}" target="_blank" rel="noopener">SCSA Computer Science</a>.</p><nav class="chapter-nav no-print">${position>0?`<a href="#${order[position-1]}">← Previous chapter</a>`:'<a href="#contents">← Contents</a>'}${position<order.length-1?`<a href="#${order[position+1]}">Next chapter →</a>`:ch.next?`<a href="${ch.next}">Next planned chapter →</a>`:'<a href="#teaching">View teaching sequence →</a>'}</nav></article>`}
function downloadText(text,name){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function render(){const route=currentTextbookRoute();const ch=chapters.find(c=>c.id===route);if(ch){document.querySelector('main').innerHTML=lessonPage(ch)+footer;window.scrollTo(0,0);if(ch.code)document.querySelector('#chapter-download').onclick=()=>downloadText(ch.code,`${ch.id}_example.py`);document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{const correct=Number(b.dataset.choice)===ch.quiz.answer;document.querySelector('#chapter-feedback').textContent=(correct?'Correct. ':'Try again. ')+ch.quiz.explanation});document.title=ch.title+' | CS ATAR';}else if(route==='assessments'){document.querySelector('main').innerHTML=assessmentHubPage()+footer;window.scrollTo(0,0);document.title='Assessments | CS ATAR';}else if(route==='audits'){document.querySelector('main').innerHTML=auditHubPage()+footer;window.scrollTo(0,0);document.title='Coverage & audits | CS ATAR';}else if(route==='unit4-coverage'){document.querySelector('main').innerHTML=unit4CoveragePage()+footer;window.scrollTo(0,0);document.title='Unit 4 coverage audit | CS ATAR';}else if(route==='unit3-evidence'){document.querySelector('main').innerHTML=unit3EvidencePage()+footer;window.scrollTo(0,0);document.title='Unit 3 practical evidence | CS ATAR';}else if(route==='unit3-coverage'){document.querySelector('main').innerHTML=unit3CoveragePage()+footer;window.scrollTo(0,0);document.title='Unit 3 coverage audit | CS ATAR';}else if(route==='unit2-coverage'){document.querySelector('main').innerHTML=unit2CoveragePage()+footer;window.scrollTo(0,0);document.title='Unit 2 coverage audit | CS ATAR';}else if(route==='coverage'){document.querySelector('main').innerHTML=coveragePage()+footer;window.scrollTo(0,0);document.title='Unit 1 coverage audit | CS ATAR';}else if(route==='teaching'){window.location.replace((location.protocol==='file:'?'teachers/index.html':'teachers/')+'?view=week');return;}else{renderLegacy();document.title=(route==='selection'?'Making decisions with selection':route==='glossary'?'Glossary':'Computer Science ATAR')+' | Classroom Textbook';if(route==='selection'){const nav=document.createElement('nav');nav.className='chapter-nav no-print';nav.innerHTML='<a href="#representation">← Previous chapter</a><a href="#loops">Next chapter →</a>';document.querySelector('.lesson').append(nav);}}}
// Heading jumps stay within the current chapter, preserving interactive attempts.
const renderTextbookDocument=render;
render=function(){const route=currentTextbookRoute(),main=document.getElementById('main'),chapter=route==='selection'||chapters.some(c=>c.id===route);if(chapter&&main.dataset.renderedChapter===route)return;renderTextbookDocument();if(chapter)main.dataset.renderedChapter=route;else delete main.dataset.renderedChapter;};
window.addEventListener('hashchange',render);render();
